// 📱 霖州往事悬浮手机 · 动态加载器
// 本体和壁纸托管在 GitHub（jsDelivr 三域备胎），版本指针在 Supabase ac_config.linzhou_phone_ref
// 拿到的提交号写进 window.__LZ_PHONE_REF__，本体照它拼壁纸地址 —— 脚本和壁纸永远同一版
(async function () {
  var L = function (m) { try { console.log('[霖州手机 loader] ' + m); } catch (e) {} };
  var ref = 'main', how = '';
  try {
    var c0 = (typeof AbortController !== 'undefined') ? new AbortController() : null;
    var t0 = c0 ? setTimeout(function () { c0.abort(); }, 6000) : null;
    var r0 = await fetch('https://hieylivlsdmyznviumht.supabase.co/rest/v1/ac_config?key=eq.linzhou_phone_ref&select=value', { cache: 'no-store', signal: c0 ? c0.signal : undefined,
      headers: { 'apikey': 'sb_publishable_MH80Xnlm1oHli6UXwzRpNA_EsC1DnCO', 'Authorization': 'Bearer sb_publishable_MH80Xnlm1oHli6UXwzRpNA_EsC1DnCO' } });
    if (t0) clearTimeout(t0);
    if (r0.ok) {
      var j0 = await r0.json();
      var v0 = j0 && j0[0] && String(j0[0].value || '').trim();
      if (v0 && /^[A-Za-z0-9._-]{4,60}$/.test(v0)) { ref = v0; how = '指针'; }   // 只认提交号/标签这种干净字符，防路径注入
      else L('指针返回了但没有可用的值：' + JSON.stringify(j0).slice(0, 100));
    } else L('指针 HTTP ' + r0.status);
  } catch (e0) { L('指针请求抛错：' + ((e0 && e0.message) || e0)); }
  if (ref === 'main') {
    try {
      var c1 = (typeof AbortController !== 'undefined') ? new AbortController() : null;
      var t1 = c1 ? setTimeout(function () { c1.abort(); }, 6000) : null;
      var r1 = await fetch('https://api.github.com/repos/fannnnnnn5822/linzhou-phone/commits/main', { cache: 'no-store', signal: c1 ? c1.signal : undefined, headers: { 'Accept': 'application/vnd.github+json' } });
      if (t1) clearTimeout(t1);
      if (r1.ok) {
        var j1 = await r1.json();
        var v1 = j1 && String(j1.sha || '').trim();
        if (v1 && /^[0-9a-f]{7,40}$/.test(v1)) { ref = v1; how = 'GitHub API'; }
      } else L('GitHub API HTTP ' + r1.status);
    } catch (e1) { L('GitHub API 抛错：' + ((e1 && e1.message) || e1)); }
  }
  if (ref === 'main') L('指针和 GitHub API 都没拿到，退回 @main（CDN 缓存可能不是最新）');
  try { window.__LZ_PHONE_REF__ = ref; } catch (eR) {}
  var urls = ["testingcf.jsdelivr.net","fastly.jsdelivr.net","cdn.jsdelivr.net"].map(function (h) {
    return 'https://' + h + '/gh/fannnnnnn5822/linzhou-phone@' + ref + '/dist/phone.js';
  });
  var code = null, lastErr = null;
  for (var i = 0; i < urls.length; i++) {
    try {
      // 被墙的域不是报错是挂死 → 12 秒闸刀，砍了换下一个源
      var ctrl = (typeof AbortController !== 'undefined') ? new AbortController() : null;
      var timer = ctrl ? setTimeout(function () { ctrl.abort(); }, 12000) : null;
      var resp = await fetch(urls[i], { cache: 'no-store', signal: ctrl ? ctrl.signal : undefined });
      if (timer) clearTimeout(timer);
      if (!resp.ok) throw new Error('HTTP ' + resp.status);
      code = await resp.text();
      if (!code || code.length < 1000) throw new Error('内容异常(' + (code ? code.length : 0) + ' chars)');
      L('@' + ref.slice(0, 7) + (how ? '（来自' + how + '）' : '') + ' via ' + urls[i].split('/')[2] + ' (' + code.length + ' chars)');
      break;
    } catch (e) { lastErr = e; code = null; L('源' + (i + 1) + ' ' + urls[i].split('/')[2] + ' 失败：' + ((e && e.message) || e)); }
  }
  if (code == null) {
    try { toastr.error('手机脚本加载失败（三个源都不通，多半是断网，刷新酒馆重试）：' + ((lastErr && lastErr.message) || lastErr), '📱 霖州往事悬浮手机'); } catch (e2) {}
    L('全部源失败');
    return;
  }
  try { eval(code); } catch (e3) {
    try { toastr.error('手机脚本执行出错：' + ((e3 && e3.message) || e3), '📱 霖州往事悬浮手机'); } catch (e4) {}
    L('eval 失败：' + ((e3 && e3.message) || e3));
  }
})();
